-- GENERATED by scripts/build_semantic_layer.py from dbt/seeds/kpi_catalogue.csv - do not edit.
-- PUBLIC table of group figures: the public metrics of the semantic layer for every group
-- (all companies, sector group, peer group, ranking group, size band, ownership type) and
-- financial year. Each expression is the one MetricFlow uses for the metric of the same name;
-- tests/test_semantic_layer.py compares every cell with `mf query`.
-- Rule: a group statistic (ratio, median, average, share) is empty when fewer than 5 companies
-- stand behind it; plain counts are always shown. Restatement figures are empty for a year with
-- no later filing yet (never 0). suppressed_reason says which applies.
-- Sums of filed values (the numerators and denominators) are not columns of this table.
-- Policy: docs/publication_policy.md. Guide: docs/semantic_layer.md.
-- noqa: disable=LT05,AM04

with company_year as (
    select * from {{ ref('sem_company_year') }}
),

-- every company-year once per kind of group it belongs to
company_groups as (
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'all' as group_type,
        'All companies' as group_value
    from company_year
    union all
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'sector_group' as group_type,
        sector_group as group_value
    from company_year
    union all
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'peer_group' as group_type,
        peer_group as group_value
    from company_year
    union all
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'ranking_group' as group_type,
        ranking_group as group_value
    from company_year
    union all
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'size_band' as group_type,
        size_band as group_value
    from company_year
    union all
    select
        company_year_key,
        fiscal_year_label as group_fiscal_year_label,
        'ownership_type' as group_type,
        ownership_type as group_value
    from company_year
),

company_year_rows as (
    select
        company_groups.group_type,
        company_groups.group_value,
        company_groups.group_fiscal_year_label,
        fact.*
    from company_groups
    inner join {{ ref('sem_company_year') }} as fact
        on company_groups.company_year_key = fact.company_year_key
    where company_groups.group_value is not null
),

company_year_metrics as (
    select
        group_type,
        group_value,
        group_fiscal_year_label as fiscal_year_label,
        sum(case when ghg_s12_tco2e is not null and turnover_cr <> 0 then ghg_s12_tco2e end)
        / nullif(sum(case when ghg_s12_tco2e is not null and turnover_cr <> 0 then turnover_cr end), 0) as ghg_intensity_agg,
        percentile_cont(0.5) within group (order by ghg_intensity_tco2e_per_cr) as ghg_intensity_median,
        cast(count(distinct case when ghg_intensity_tco2e_per_cr is not null then isin end) as integer) as companies_with_ghg_intensity,
        sum(case when energy_total_gj is not null and turnover_cr <> 0 then energy_total_gj end)
        / nullif(sum(case when energy_total_gj is not null and turnover_cr <> 0 then turnover_cr end), 0) as energy_intensity_agg,
        percentile_cont(0.5) within group (order by energy_intensity_gj_per_cr) as energy_intensity_median,
        cast(count(distinct case when energy_intensity_gj_per_cr is not null then isin end) as integer) as companies_with_energy_intensity,
        sum(case when water_consumption_kl is not null and turnover_cr <> 0 then water_consumption_kl end)
        / nullif(sum(case when water_consumption_kl is not null and turnover_cr <> 0 then turnover_cr end), 0) as water_intensity_agg,
        percentile_cont(0.5) within group (order by water_intensity_kl_per_cr) as water_intensity_median,
        cast(count(distinct case when water_intensity_kl_per_cr is not null then isin end) as integer) as companies_with_water_intensity,
        sum(case when waste_generated_t is not null and turnover_cr <> 0 then waste_generated_t end)
        / nullif(sum(case when waste_generated_t is not null and turnover_cr <> 0 then turnover_cr end), 0) as waste_intensity_agg,
        percentile_cont(0.5) within group (order by waste_intensity_t_per_cr) as waste_intensity_median,
        cast(count(distinct case when waste_intensity_t_per_cr is not null then isin end) as integer) as companies_with_waste_intensity,
        sum(case when energy_renewable_gj is not null and energy_total_gj <> 0 then 100.0 * energy_renewable_gj end)
        / nullif(sum(case when energy_renewable_gj is not null and energy_total_gj <> 0 then energy_total_gj end), 0) as renewable_share_agg,
        cast(count(distinct case when renewable_share_pct is not null then isin end) as integer) as companies_with_renewable_share,
        sum(case when headcount_female is not null and headcount_total <> 0 then 100.0 * headcount_female end)
        / nullif(sum(case when headcount_female is not null and headcount_total <> 0 then headcount_total end), 0) as female_workforce_agg,
        cast(count(distinct case when female_workforce_pct is not null then isin end) as integer) as companies_with_female_workforce,
        cast(count(distinct isin) as integer) as companies_reporting,
        sum(case when (scope3_disclosed) and (true) then 100.0 else 0 end)
        / nullif(sum(case when true then 1 else 0 end), 0) as scope3_disclosed_share
    from company_year_rows
    group by group_type, group_value, group_fiscal_year_label
),

disclosure_quality_rows as (
    select
        company_groups.group_type,
        company_groups.group_value,
        company_groups.group_fiscal_year_label,
        fact.*
    from company_groups
    inner join {{ ref('sem_disclosure_quality') }} as fact
        on company_groups.company_year_key = fact.company_year_key
    where company_groups.group_value is not null
),

disclosure_quality_metrics as (
    select
        group_type,
        group_value,
        group_fiscal_year_label as fiscal_year_label,
        avg(dqs_total) as dqs_avg,
        percentile_cont(0.5) within group (order by dqs_total) as dqs_median,
        sum(case when (dqs_grade = 'A') and (dqs_grade <> 'insufficient_data') then 100.0 else 0 end)
        / nullif(sum(case when dqs_grade <> 'insufficient_data' then 1 else 0 end), 0) as dqs_grade_a_share,
        avg(dqs_voluntary_depth) as voluntary_depth_avg,
        cast(count(distinct case when dqs_total is not null then isin end) as integer) as companies_with_dqs,
        cast(count(distinct case when nullif(dqs_grade, 'insufficient_data') is not null then isin end) as integer) as companies_with_dqs_grade,
        cast(count(distinct case when dqs_voluntary_depth is not null then isin end) as integer) as companies_with_voluntary_depth
    from disclosure_quality_rows
    group by group_type, group_value, group_fiscal_year_label
),

restatement_rows as (
    select
        company_groups.group_type,
        company_groups.group_value,
        company_groups.group_fiscal_year_label,
        fact.*
    from company_groups
    inner join {{ ref('sem_restatement') }} as fact
        on company_groups.company_year_key = fact.company_year_key
    where company_groups.group_value is not null
),

restatement_metrics as (
    select
        group_type,
        group_value,
        group_fiscal_year_label as fiscal_year_label,
        cast(sum(case when classification = 'material' then 1 else 0 end) as integer) as material_restatements,
        sum(case when (classification = 'material') and (is_compared) then 100.0 else 0 end)
        / nullif(sum(case when is_compared then 1 else 0 end), 0) as material_restatement_share,
        cast(sum(case when classification = 'suspected_scale_error' then 1 else 0 end) as integer) as suspected_scale_errors,
        cast(count(distinct case when nullif(is_compared, false) is not null then isin end) as integer) as companies_with_compared_restatements
    from restatement_rows
    group by group_type, group_value, group_fiscal_year_label
),

-- restatements of a year are known only once a later year has been filed
latest as (
    select max(fiscal_year_label) as latest_fiscal_year_label from company_year
),

-- counts: 0 when the group has no row, empty when the year cannot be observed yet
joined as (
    select
        company_year_metrics.group_type,
        company_year_metrics.group_value,
        company_year_metrics.fiscal_year_label,
        company_year_metrics.fiscal_year_label < latest.latest_fiscal_year_label as has_later_filing,
        company_year_metrics.ghg_intensity_agg,
        company_year_metrics.ghg_intensity_median,
        coalesce(company_year_metrics.companies_with_ghg_intensity, 0) as companies_with_ghg_intensity,
        company_year_metrics.energy_intensity_agg,
        company_year_metrics.energy_intensity_median,
        coalesce(company_year_metrics.companies_with_energy_intensity, 0) as companies_with_energy_intensity,
        company_year_metrics.water_intensity_agg,
        company_year_metrics.water_intensity_median,
        coalesce(company_year_metrics.companies_with_water_intensity, 0) as companies_with_water_intensity,
        company_year_metrics.waste_intensity_agg,
        company_year_metrics.waste_intensity_median,
        coalesce(company_year_metrics.companies_with_waste_intensity, 0) as companies_with_waste_intensity,
        company_year_metrics.renewable_share_agg,
        coalesce(company_year_metrics.companies_with_renewable_share, 0) as companies_with_renewable_share,
        company_year_metrics.female_workforce_agg,
        coalesce(company_year_metrics.companies_with_female_workforce, 0) as companies_with_female_workforce,
        coalesce(company_year_metrics.companies_reporting, 0) as companies_reporting,
        company_year_metrics.scope3_disclosed_share,
        disclosure_quality_metrics.dqs_avg,
        disclosure_quality_metrics.dqs_median,
        disclosure_quality_metrics.dqs_grade_a_share,
        disclosure_quality_metrics.voluntary_depth_avg,
        coalesce(disclosure_quality_metrics.companies_with_dqs, 0) as companies_with_dqs,
        coalesce(disclosure_quality_metrics.companies_with_dqs_grade, 0) as companies_with_dqs_grade,
        coalesce(disclosure_quality_metrics.companies_with_voluntary_depth, 0) as companies_with_voluntary_depth,
        case
            when company_year_metrics.fiscal_year_label < latest.latest_fiscal_year_label
                then coalesce(restatement_metrics.material_restatements, 0)
        end as material_restatements,
        restatement_metrics.material_restatement_share,
        case
            when company_year_metrics.fiscal_year_label < latest.latest_fiscal_year_label
                then coalesce(restatement_metrics.suspected_scale_errors, 0)
        end as suspected_scale_errors,
        case
            when company_year_metrics.fiscal_year_label < latest.latest_fiscal_year_label
                then coalesce(restatement_metrics.companies_with_compared_restatements, 0)
        end as companies_with_compared_restatements
    from company_year_metrics
    cross join latest
    left join disclosure_quality_metrics
        on
            company_year_metrics.group_type = disclosure_quality_metrics.group_type
            and company_year_metrics.group_value = disclosure_quality_metrics.group_value
            and company_year_metrics.fiscal_year_label = disclosure_quality_metrics.fiscal_year_label
    left join restatement_metrics
        on
            company_year_metrics.group_type = restatement_metrics.group_type
            and company_year_metrics.group_value = restatement_metrics.group_value
            and company_year_metrics.fiscal_year_label = restatement_metrics.fiscal_year_label
)

select
    group_type,
    group_value,
    fiscal_year_label,
    case when companies_with_ghg_intensity >= 5 then ghg_intensity_agg end as ghg_intensity_agg,
    case when companies_with_ghg_intensity >= 5 then ghg_intensity_median end as ghg_intensity_median,
    companies_with_ghg_intensity,
    case when companies_with_energy_intensity >= 5 then energy_intensity_agg end as energy_intensity_agg,
    case when companies_with_energy_intensity >= 5 then energy_intensity_median end as energy_intensity_median,
    companies_with_energy_intensity,
    case when companies_with_water_intensity >= 5 then water_intensity_agg end as water_intensity_agg,
    case when companies_with_water_intensity >= 5 then water_intensity_median end as water_intensity_median,
    companies_with_water_intensity,
    case when companies_with_waste_intensity >= 5 then waste_intensity_agg end as waste_intensity_agg,
    case when companies_with_waste_intensity >= 5 then waste_intensity_median end as waste_intensity_median,
    companies_with_waste_intensity,
    case when companies_with_renewable_share >= 5 then renewable_share_agg end as renewable_share_agg,
    companies_with_renewable_share,
    case when companies_with_female_workforce >= 5 then female_workforce_agg end as female_workforce_agg,
    companies_with_female_workforce,
    companies_reporting,
    case when companies_reporting >= 5 then scope3_disclosed_share end as scope3_disclosed_share,
    case when companies_with_dqs >= 5 then dqs_avg end as dqs_avg,
    case when companies_with_dqs >= 5 then dqs_median end as dqs_median,
    case when companies_with_dqs_grade >= 5 then dqs_grade_a_share end as dqs_grade_a_share,
    case when companies_with_voluntary_depth >= 5 then voluntary_depth_avg end as voluntary_depth_avg,
    companies_with_dqs,
    companies_with_dqs_grade,
    companies_with_voluntary_depth,
    material_restatements,
    case when companies_with_compared_restatements >= 5 then material_restatement_share end as material_restatement_share,
    suspected_scale_errors,
    companies_with_compared_restatements,
    nullif(
        concat_ws(
            '|',
            case
                when
                    least(companies_reporting, companies_with_dqs, companies_with_dqs_grade, companies_with_energy_intensity, companies_with_female_workforce, companies_with_ghg_intensity, companies_with_renewable_share, companies_with_voluntary_depth, companies_with_waste_intensity, companies_with_water_intensity) < 5
                    or (has_later_filing and companies_with_compared_restatements < 5)
                    then 'fewer_than_5_companies'
            end,
            case when not has_later_filing then 'not_yet_observable' end
        ),
        ''
    ) as suppressed_reason
from joined
